SELECT URLHash, EventDate, COUNT(*) AS PageViews FROM ${database}.${schema}.hits WHERE CounterID = 62 AND EventDate >= DATE '2013-07-01' AND EventDate <= DATE '2013-07-31' AND IsRefresh = 0 AND TraficSourceID IN (-1, 6) AND RefererHash = 3594120000172545465 GROUP BY URLHash, EventDate ORDER BY PageViews, URLHash DESC OFFSET 100 LIMIT 10;
